const keep=new Set(['readFirst','ownerPreviewPolicy','activeExecutionSessions','full71AndEightIdeasPreserved','wholeSuitePassing','completeReleaseRun','completeReleaseFollowups','currentInstalled','latestCoordination','latestChecklistUpdate','latestFailureInventory','releaseTerminalCheckpoint','latestNativeBuild','lowerLimbNerveCoverage','latestSourceRecovery','next','beforeFurtherWork','nextExecutionHandoff','lastPriorityReassessment','latestVerifiedWebsite','pendingKeyboardGuide','pendingSavedStudyPlan','latestCurrentTestContext','pendingBoundedStockCampaign','currentDeliveryLifecycleNext','currentContextFollowup','latestPublishedUltrasoundSource','latestLowerLimbNerveSourceStudy','linkedLearningNextAudit','latestEducationResponseContract','latestVerifierMemoryControl','currentReleaseContextMap','latestAssessmentAvailabilityCheckpoint']);
for(const key of keep)assert(Object.hasOwn(current,key),'Required current field '+key);
const archivedKeys=Object.keys(current).filter(k=>!keep.has(k)),dir='F:/VisibleMedicine/recovery/checkpoints/20261026-compact-current-index';assert(!fs.existsSync(dir));fs.mkdirSync(dir,{recursive:true});fs.copyFileSync(file,dir+'/CURRENT_INDEX_BEFORE.json',fs.constants.COPYFILE_EXCL);assert.equal(hash(dir+'/CURRENT_INDEX_BEFORE.json'),beforeHash);
const archive={path:dir+'/CURRENT_INDEX_BEFORE.json',sha256:beforeHash};for(const key of archivedKeys)delete current[key];
current.savedHistoricalFieldIndex={...archive,jsonPathPrefix:'activeWork.current.',keys:archivedKeys,meaning:'Complete original values are retained at original JSON paths; some are old pending/historical records. Missing current keys never imply completion, approval or permission. Inspect only relevant prior records, not the whole archive.'};
const restored=structuredClone(current);delete restored.savedHistoricalFieldIndex;for(const key of archivedKeys)restored[key]=old.activeWork.current[key];assert.deepEqual(restored,old.activeWork.current);
next.historyArchive={...archive,format:'Complete former index at its original JSON paths, including the prior historyArchive chain.',allHistoryRetained:true,readPolicy:'Read only relevant older fields; absence never implies approval/completion/permission.'};
next.indexPolicy={...(old.indexPolicy??{}),currentIndexIsCompact:true,olderFieldsLookup:'activeWork.current.savedHistoricalFieldIndex',allOriginalJsonPathsRecoverable:true};
assert.deepEqual(next.goal,old.goal);assert.deepEqual(next.safety,old.safety);assert.deepEqual(current.ownerPreviewPolicy,old.activeWork.current.ownerPreviewPolicy);assert.deepEqual(current.activeExecutionSessions,old.activeWork.current.activeExecutionSessions);assert.deepEqual(current.currentInstalled,old.activeWork.current.currentInstalled);assert.deepEqual(current.latestVerifiedWebsite,old.activeWork.current.latestVerifiedWebsite);assert.deepEqual(current.pendingSavedStudyPlan,old.activeWork.current.pendingSavedStudyPlan);
const bytes=Buffer.from(JSON.stringify(next,null,2)+'\n');assert(bytes.length<40000);assert.equal(hash(file),beforeHash,'Concurrent index update; do not overwrite it');fs.writeFileSync(file,bytes);
const result={at:new Date().toISOString(),passing:true,before:archive,beforeBytes:fs.statSync(archive.path).size,after:{path:file,sha256:hash(file),bytes:bytes.length},archivedFieldCount:archivedKeys.length,retainedCurrentFields:keep.size,fullFormerCurrentObjectReconstructionExact:true,goalSafetyPoliciesInstalledCandidateAndActualJobHandlesUnchanged:true,notLivenessOrCompletionProof:true};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(result));
